  modelName?: string;
  // Add other filterable fields if needed
}

// GET ALL — POST /all_factoryRunUsages
export async function getAllFactoryRunUsages(filter?: FactoryRunUsageFilter): Promise<FactoryRunUsage[]> {
  const payload = filter ? { factoryRunUsages: [filter] } : { factoryRunUsages: [{}] };
  const res = await fetch(BASE_URL + "/all_factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: FactoryRunUsageListResponse = await res.json();
  return data.factoryRunUsages ?? []; // unwrap: SP wraps array under plural key
}

// GET ONE — POST /one_factoryRunUsages
export async function getFactoryRunUsageById(id: number): Promise<FactoryRunUsage | null> {
  const res = await fetch(BASE_URL + "/one_factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ factoryRunUsages: [{ factoryRunUsageId: id }] }),
  });
